// DELIVERABLE 1 — 60-provider data source catalogue. Every monetary figure carries exactly one
// provenance marker — [ACTUAL] / [LIST] / [QUOTE] / [DERIVED] / [ASSUMPTION] / [OFFICIAL] /
// [UNKNOWN] — and no unpublished price bracket appears. Vendor prices are quoted in the currency
// the vendor publishes; one FX rate everywhere: RBA, 21 Aug 2026 — USD 0.7145 per A$1.
// costMin/costMax (AUD/yr, filter metadata only) are set only where a published price or its
// RBA conversion exists; null = quote-only / unpriced / [UNKNOWN].
export type ProviderCategory = 'A' | 'B' | 'C' | 'D' | 'E' | 'F';

// The six categories: first-party transactions, demographics, competitive intelligence,
// enrichment, compliance and geospatial.
export const CATEGORY_LABELS: Record<ProviderCategory, string> = {
  A: 'First-Party Transactions & Market Intelligence',
  B: 'Customer & Demographic',
  C: 'Competitive Intelligence',
  D: 'Marketing & Brand / Enrichment',
  E: 'Regulatory & Compliance',
  F: 'Technology / Geospatial',
};

// Trust ladder, in order:
// official statistic > audited filing > licensed panel > aggregator > modelled estimate.
// An aggregator may point to a primary source but may never be one; a modelled estimate may
// never feed a headline or a funded figure.
export type TrustTier =
  | 'Official statistic'
  // A third party's audited filing, retrieved first-hand. Exactly one provider carries it
  // (id 31, Live Nation). This is a SOURCE TRUST TIER, not a provenance marker: it ranks one
  // rung below an official statistic.
  | 'Audited filing'
  // A public filing exists but was never captured — e.g. id 32, StubHub/viagogo, whose investor
  // site returned 403. Distinct from 'Audited filing' so no uncaptured filing is ever cited as
  // audited content.
  | 'Public filing — not captured'
  | 'Primary record — conditional'
  | 'Platform record'
  | 'Licensed panel'
  | 'Aggregator'
  | 'Aggregator (channel)'
  | 'Aggregator (tool)'
  | 'Modelled estimate';

// Market coverage tags per provider, taken verbatim from the provider manifest that accompanies the
// prototype extracts (the authoritative tag set); 'Europe' there is carried here as 'EU'. 'Global'
// is a tag in its own right, not a shorthand for every market: a Global source is not thereby an
// AU/UK/US/CA/EU source, and a country tag records where a source has coverage, never that the
// source evidences demand in that market.
export type ProviderCountry = 'AU' | 'UK' | 'US' | 'CA' | 'EU' | 'IN' | 'Global';

// The six markets offered as filters. 'IN' is a coverage tag on the India-operations rows, not a
// target market, so it is not offered as a filter; every row carrying it also carries AU.
export const COUNTRY_FILTERS: ProviderCountry[] = ['AU', 'UK', 'US', 'CA', 'EU', 'Global'];

export interface Provider {
  id: number;
  name: string;
  countries: ProviderCountry[];
  category: ProviderCategory;
  paid: 'Paid' | 'Free' | 'Internal' | 'Platform' | 'Mixed';
  url: string;
  urlVerified: boolean;
  coverage: string;
  quality: string;
  trustTier: TrustTier;
  costLabel: string;
  costMin: number | null; // AUD/yr; null = quote-only / usage / unknown
  costMax: number | null;
  refresh: string;
  sample: string;
  gdpr: string;
  latency: string;
  complexity: string;
  historicalDepth: string;
  api: string;
  recommendation: 1 | 2 | 3 | 4 | 5;
  notes: string;
}

